dirs=['docs/coop/design-corrections/foundation','docs/coop/design-corrections/native','docs/coop/design-corrections/workflows','docs/coop/design-corrections/security','docs/coop/artifacts','docs/coop/completion','docs/v2']
tops=['docs/coop/design-corrections','docs/coop']
rep={}
for tree in ('base-tree','patched-tree'):
    dst=RT/'work'/tree
    if dst.exists(): raise SystemExit('exists '+str(dst))
    files=[]
    for d in dirs:
        for dp,dn,fn in os.walk(SRC/d):
            dn[:]=[x for x in dn if x!='__pycache__']
            files+= [Path(dp)/f for f in fn]
    for d in tops:
        files+= [f for f in (SRC/d).iterdir() if f.is_file()]
    bad=0
    for f in files:
        o=dst/f.relative_to(SRC); o.parent.mkdir(parents=True, exist_ok=True); shutil.copyfile(f,o)
        if f.read_bytes()!=o.read_bytes(): bad+=1
    rep[tree]={'files':len(files),'mismatches':bad}
(RT/'receipts/copy-trees.json').write_text(json.dumps({'source':str(SRC),'excluded':'reviews/ (not read)','trees':rep},indent=2)+chr(10))
print(rep)
"

